def _frame(images):
    if type(images) is not tuple or len(images) != 3 or any(type(x) is not bytes for x in images):
        raise TypeError('exact controller/representation/semantic-checker image tuple required')
    if any(not 0 < len(x) <= CAPACITY - 1024 for x in images):
        raise ValueError('each nonempty component must leave room for the ELF entry')
    raw = struct.pack('<6Q', PACK_MAGIC, 1, *(len(x) for x in images), 0) + b''.join(images)
    if len(raw) > CAPACITY:
        raise ValueError('the complete three-image frame exceeds the original 1 MiB bound')
    return raw

def _checked_components(values):
    from .hia_agent_assembly import assemble_program
    if type(values) is not tuple or len(values) != 2:
        raise HIAProgramRejected("exact two frozen HIA component sources required", "E_HIA_LINUX_FILE_ROUNDTRIP_COMPONENT")
    result = {}
    for (name, expected), raw in zip(COMPONENT_PINS.items(), values):
        if type(raw) is not bytes or sha256(raw).hexdigest() != expected:
            raise HIAProgramRejected("frozen component source mismatch", "E_HIA_LINUX_FILE_ROUNDTRIP_COMPONENT")
        result[name] = assemble_program(raw)
    return result
